// PulseQA Data Transformation: Filter, sort, and extract top 5 repositories
const inputData = $input.first().json;
const items = inputData.items || [];

// 1. Filter out archived or disabled repositories
const activeRepos = items.filter(r => !r.archived && !r.disabled);

// 2. Sort descending by stargazers count
activeRepos.sort((a, b) => (b.stargazers_count || 0) - (a.stargazers_count || 0));

// 3. Extract and normalize top 5 results
const top5 = activeRepos.slice(0, 5).map((r, index) => ({
  rank: index + 1,
  id: r.id,
  name: r.name,
  fullName: r.full_name,
  owner: r.owner ? r.owner.login : 'unknown',
  description: r.description ? r.description.trim() : 'No description provided.',
  stars: r.stargazers_count || 0,
  forks: r.forks_count || 0,
  language: r.language || 'Multi-language',
  url: r.html_url,
  updatedAt: r.updated_at
}));

// 4. Select #1 repository for enrichment
const topRepo = top5[0] || {};

return [{
  json: {
    top5,
    topRepo,
    enrichOwner: topRepo.owner,
    enrichRepo: topRepo.name,
    totalEvaluated: activeRepos.length,
    processedAt: new Date().toISOString()
  }
}];

// Decode Base64 README content and generate an executive excerpt
const prevData = $('Filter & Select Top 5 Repositories').first().json;
const readmeResponse = $input.first().json;

let readmePreview = 'No README documentation available.';
let readmeUrl = prevData.topRepo.url;

if (readmeResponse && readmeResponse.content) {
  try {
    // Decode base64 buffer
    const decoded = Buffer.from(readmeResponse.content, 'base64').toString('utf-8');

    // Clean markdown syntax, images, badges, code blocks, HTML
    const cleaned = decoded
      .replace(/!\[.*?\]\(.*?\)/g, '')
      .replace(/\[(.*?)\]\(.*?\)/g, '$1')
      .replace(/#+\s+/g, '')
      .replace(/`{1,3}.*?`{1,3}/gs, '')
      .replace(/<.*?>/g, '')
      .replace(/\s+/g, ' ')
      .trim();

    // 220-character executive preview
    readmePreview = cleaned.length > 220 ? cleaned.substring(0, 220) + '...' : cleaned;
    readmeUrl = readmeResponse.html_url || prevData.topRepo.url;
  } catch (e) {
    readmePreview = 'README parsing encountered an encoding exception.';
  }
}

return [{
  json: {
    ...prevData,
    readmePreview,
    readmeUrl,
    enrichedSuccessfully: !!readmeResponse.content
  }
}];

// Format Spotlight Digest (High-Interest Tier)
const data = $input.first().json;
const medals = ['🥇', '🥈', '🥉', '4️⃣', '5️⃣'];

const fields = data.top5.map(repo => ({
  name: `${medals[repo.rank - 1]} #${repo.rank} ${repo.fullName}`,
  value: `⭐ **${repo.stars.toLocaleString()}** stars · 🍴 **${repo.forks.toLocaleString()}** forks · 💻 \`${repo.language}\`\n${repo.description.substring(0, 110)}...\n[View on GitHub](${repo.url})`,
  inline: false
}));

// Append Enriched Spotlight README
fields.push({
  name: `🌟 #1 REPOSITORY SPOTLIGHT: ${data.topRepo.name.toUpperCase()}`,
  value: `> *"${data.readmePreview}"*\n[Read Full Documentation & Source](${data.readmeUrl})`,
  inline: false
});

const discordPayload = {
  username: "PulseQA Intelligence Brief",
  avatar_url: "https://cdn-icons-png.flaticon.com/512/3242/3242257.png",
  embeds: [
    {
      title: "🔥 PulseQA GitHub Spotlight Brief · High-Interest Tier",
      description: `**Daily intelligence brief** highlighting trending repositories worldwide.\nEvaluated **${data.totalEvaluated}** active repositories; #1 project boasts over **${data.topRepo.stars.toLocaleString()}** stars!`,
      color: 3066993, // #2ECC71 Emerald Green
      fields: fields,
      footer: {
        text: `PulseQA Automation Engine · Automated via n8n · ${data.processedAt}`
      }
    }
  ]
};

return [{ json: { ...data, discordPayload } }];

// Format Standard Digest (Regular Tier)
const data = $input.first().json;
const medals = ['1️⃣', '2️⃣', '3️⃣', '4️⃣', '5️⃣'];

const fields = data.top5.map(repo => ({
  name: `${medals[repo.rank - 1]} #${repo.rank} ${repo.fullName}`,
  value: `⭐ **${repo.stars.toLocaleString()}** stars · 🍴 **${repo.forks.toLocaleString()}** forks · 💻 \`${repo.language}\`\n${repo.description.substring(0, 110)}...\n[View on GitHub](${repo.url})`,
  inline: false
}));

const discordPayload = {
  username: "PulseQA Intelligence Brief",
  avatar_url: "https://cdn-icons-png.flaticon.com/512/3242/3242257.png",
  embeds: [
    {
      title: "📊 PulseQA GitHub Daily Digest · Standard Tier",
      description: `Daily digest of developer repositories.\nEvaluated **${data.totalEvaluated}** repositories.`,
      color: 3447003, // #3498DB Sky Blue
      fields: fields,
      footer: {
        text: `PulseQA Automation Engine · Automated via n8n · ${data.processedAt}`
      }
    }
  ]
};

return [{ json: { ...data, discordPayload } }];

// Format Error Fallback Alert
const errorData = $input.first().json;
const timestamp = new Date().toISOString();

const discordPayload = {
  username: "PulseQA Alert System",
  avatar_url: "https://cdn-icons-png.flaticon.com/512/564/564619.png",
  embeds: [
    {
      title: "⚠️ PulseQA GitHub Digest Workflow Warning",
      description: "The automated GitHub repository digest encountered an API failure or rate-limit exception during data collection.",
      color: 15158332, // #E74C3C Coral Red
      fields: [
        {
          name: "Endpoint Attempted",
          value: "`https://api.github.com/search/repositories`",
          inline: true
        },
        {
          name: "Error Details",
          value: `\`${JSON.stringify(errorData.error || errorData.message || 'API returned empty or non-200 payload')}\``,
          inline: true
        },
        {
          name: "Action Taken",
          value: "Execution gracefully routed to error fallback path. Scheduled run will re-attempt in 1 hour.",
          inline: false
        }
      ],
      footer: {
        text: `PulseQA Error Sentinel · ${timestamp}`
      }
    }
  ]
};

return [{ json: { errorData, discordPayload } }];
